document.addEventListener("DOMContentLoaded",function(){const e=document.querySelectorAll("img[loading='lazy']");if("loading"in HTMLImageElement.prototype)console.log("Browser supports native lazy loading");else{const t=new IntersectionObserver(e=>{e.forEach(e=>{if(e.isIntersecting){const n=e.target;n.src=n.dataset.src,t.unobserve(n)}})});e.forEach(e=>{t.observe(e)})}const n=performance.now();window.addEventListener("load",()=>{setTimeout(()=>{const e=performance.now()-n,t={name:"CLS",value:performance.getEntriesByType("layout-shift").reduce((e,t)=>e+t.value,0)},o={name:"LCP",value:performance.getEntriesByType("largest-contentful-paint").reduce((e,t)=>t.startTime>e?t.startTime:e,0)},a={name:"FID",value:performance.getEntriesByType("first-input").reduce((e,t)=>t.processingStart-t.startTime,0)};console.log("Page Load Time:",e+"ms"),console.log("Core Web Vitals:",t,o,a)},0)})});
